export function chapterTwo() {
 activeLab='pangloss';
 return `<article class="course-article chapter-two"><div class="chapter-hero">${tag('Chapitre 02 / Numériser les productions linguistiques humaines')}<h1>De la parole<br><em>au corpus annoté.</em></h1><div class="chapter-hero-bottom">${btn('Mode projection','#/projection-chapitre-2/0',true)}</div></div>
 <nav class="on-this-page" aria-label="Dans ce chapitre"><span>Dans cette salle</span>${[['c2-mission','De la voix aux données'],['c2-collecte','Enregistrer'],['c2-locuteurs','Qui parle quand ?'],['c2-unites','Transcrire et gloser'],['c2-pangloss','Le récit en iaai'],['c2-outils','Les outils'],['c2-transmettre','Transmettre'],['c2-sources','Sources']].map(([id,label])=>`<a href="#${id}" data-scroll="${id}">${label}</a>`).join('')}</nav>
 <section class="lesson-section" id="c2-mission"><div class="section-kicker">LE POINT DE DÉPART</div><h2>Une production humaine.<br>Plusieurs représentations.</h2><p>Pour être utilisable par ses locuteurs, ses enseignants ou la communauté scientifique, les productions orales suivent un parcours d’enregistrement, de numérisation et d’annotation.</p>
 <div class="c2-chain" aria-label="De la production linguistique au corpus"><span>Situation de parole</span><b>→</b><span>Signal audio numérique</span><b>→</b><span>Segments et locuteurs</span><b>→</b><span>Transcription</span><b>→</b><span>Mots, gloses, traductions</span></div>
 <p>Deux transformations se complètent. La <strong>numérisation du signal</strong> représente le son par des nombres. L’<strong>annotation linguistique</strong> relie ce signal à des descripteurs symboliques.</p>
 
 ${callout('Notre fil conducteur','Notre fil conducteur est une histoire racontée par Taï Waheo à Françoise Ozanne-Rivière, dans une langue Kanak appelée le iaai. '+ref('pangloss','Consulter le récit dans Pangloss'))}</section>
 <section class="lesson-section" id="c2-collecte"><div class="section-kicker">01 / ENREGISTRER ET NUMÉRISER</div><h2>Consentement éclairé,<br><em>contexte, et qualité technique.</em></h2>
 <ol class="critical-list"><li><span>Avant : Un contexte clair et des consentements éclairés.</span><p>Avant tout, être sûr que les participants ont bien compris la raison de l’enregistrement et ont donné leur accord pour les usages prévus. Distinguer travail en classe, archivage, diffusion publique et réutilisations. Préciser le responsable, les accès, la durée de conservation et le moyen de retirer son consentement ; conserver une trace datée de l’information et des réponses. Sur le plan technique, choisir le format, la fréquence d’échantillonnage et la profondeur en bits ; vérifier le niveau d’entrée. ${ref('cnil-consent','Guide de la CNIL sur le consentement')}</p></li><li><span>Pendant : vérifier la prise de son</span><p>Faites un essai au casque ; placez le microphone pour rendre les voix intelligibles et limitez les frottements et bruits parasites. Réglez le gain avec une marge pour les passages les plus forts et surveillez le signal au casque pendant la prise. Notez appareil, microphone, distance, canaux, interruptions et changements de dispositif. Ne pas oublier qu’un bruit parasite est toujours bien plus présent sur un enregistrement qu’on ne le pense. Et le tout en restant dans l’écoute active du ou des locuteurs !</p></li><li><span>Après : distinguer conservation et consultation</span><p>Pour une nouvelle prise, privilégiez un fichier WAV PCM non compressé. Conservez toujours l’original tel qu’il a été produit, même si seul un fichier compressé existe : le convertir en WAV ne recrée pas les informations perdues. Travaillez sur une copie et documentez toute conversion, tout filtrage ou montage. Une copie MP3 peut faciliter la consultation. Vérifiez les sauvegardes et la réouverture des fichiers. Si un enregistrement est inaudible, il faut le savoir tout de suite pour le refaire tant que l’on est sur place.</p></li></ol>
 </section>
 <section class="lesson-section" id="c2-locuteurs"><div class="section-kicker">02 / QUI PARLE QUAND ?</div><h2>Diarisation : segmenter<br>et regrouper par locuteur.</h2><p>Le terme anglais <em>speaker diarization</em> correspond à la <strong>segmentation et au regroupement en locuteurs</strong>, aussi appelée <strong>diarisation</strong>. On délimite des intervalles de parole et on regroupe ceux attribués à une même voix : LOC_01, LOC_02… L’identité civile des personnes n’est pas nécessaire pour effectuer ce regroupement.</p>
 <div class="c2-table-wrap"><table><caption>Des questions distinctes sur le même signal</caption><thead><tr><th>Opération</th><th>Question</th><th>Résultat</th></tr></thead><tbody><tr><td>Détection de parole</td><td>Y a-t-il de la parole ici ?</td><td>Intervalles de parole, silences ou autres sons.</td></tr><tr><td>Diarisation</td><td>Qui parle ?</td><td>Intervalles attribués à des identifiants de locuteurs.</td></tr><tr><td>Identification</td><td>À quelle personne correspond cet identifiant ?</td><td>Lien documenté vers une personne, si disponible et approprié.</td></tr></tbody></table></div>
 <p>Un changement de locuteur n’est pas forcément une frontière de phrase. Une pause n’implique pas un nouveau locuteur. Deux personnes peuvent parler simultanément : leurs intervalles se chevauchent alors sur des pistes distinctes. Une voix incertaine doit rester indiquée comme telle.</p>
 <p>Des <strong>modèles spécialisés</strong> peuvent proposer une première diarisation. La bibliothèque libre <strong>pyannote.audio</strong> combine des modèles de segmentation de la parole et de représentation des voix, puis regroupe les segments attribués à un même locuteur. Sa chaîne préentraînée <strong>Community-1</strong> produit des intervalles horodatés associés à des identifiants de locuteurs ; elle peut fonctionner sur l’ordinateur après téléchargement des modèles. Ces propositions servent de point de départ : réécoutez les changements de voix et les chevauchements, corrigez les regroupements et vérifiez les bornes. La qualité varie selon les enregistrements ; conservez la version automatique et la version corrigée pour documenter vos interventions. ${ref('pyannote','pyannote.audio')} · ${ref('pyannote-community','Documentation de Community-1')}</p>
 </section>
 <section class="lesson-section" id="c2-unites"><div class="section-kicker">03 / DE L’ÉNONCÉ AUX UNITÉS LINGUISTIQUES</div><h2>Transcrire, segmenter,<br><em>gloser, traduire.</em></h2><p>Une annotation relie une portion de source à une information, selon une convention et avec une provenance : auteur, date et version. Le temps, les caractères et les unités linguistiques ne sont pas interchangeables. La transcription se vérifie à l’écoute ; la traduction et les gloses se discutent avec des personnes compétentes dans la langue. Les incertitudes restent signalées.</p>
 <p>Le <strong>Speech-to-Text (STT)</strong>, ou reconnaissance automatique de la parole, produit une proposition de transcription à partir d’un enregistrement. On rencontre aussi le sigle <strong>ASR</strong> (<em>Automatic Speech Recognition</em>). Pour une langue disposant de peu d’audio transcrit, une méthode consiste à adapter un modèle déjà préentraîné à l’aide d’un corpus où chaque extrait sonore est associé à sa transcription vérifiée : c’est l’<strong>ajustement fin</strong> (<em>fine-tuning</em>). La préparation de ces exemples, les conventions d’écriture et la vérification des résultats à l’écoute restent une part essentielle du travail. ${ref('wav2vec2','Baevski et al., 2020')}</p>
 <p>Un exemple récent concerne le <strong>marquisien et le māori des îles Cook</strong>. Marie Tearere Teikitohe Curieux (Marie Teikitohe dans la publication), Rolando Coto-Solano et Sally Akevai Nicholas présentent à <strong>Interspeech 2026</strong> des expériences à partir de 17 heures de parole naturelle transcrite en marquisien, recueillies auprès de 38 locuteurs, et de 4 heures en māori des îles Cook. L’équipe adapte plusieurs modèles multilingues ; Wav2Vec2, complété par un modèle de langue construit avec KenLM, donne les meilleurs résultats pour le marquisien dans cette comparaison. L’entraînement conjoint sur les deux langues n’apporte qu’un faible gain au marquisien et aucun au māori des îles Cook. Les essais montrent aussi l’intérêt de corriger une transcription automatique pour accélérer la documentation, tout en soulignant les difficultés liées aux noms propres, aux frontières de mots, aux bruits et aux voix superposées. ${ref('teikitohe-2026','Teikitohe, Coto-Solano et Nicholas, 2026')}</p>
 <div class="c2-table-wrap"><table><caption>Les couches d’une ressource linguistique</caption><thead><tr><th>Couche</th><th>Ce qu’elle apporte</th><th>Choix à documenter</th></tr></thead><tbody><tr><td>Transcription</td><td>Les formes produites, dans une orthographe choisie ou une notation phonétique. ${ref('ipa','Alphabet phonétique international (API)')}</td><td>Système d’écriture, hésitations, répétitions, passages inaudibles ; une normalisation est une autre version.</td></tr><tr><td>Alignement temporel</td><td>Un début et une fin dans le média pour une unité transcrite.</td><td>Secondes ou millisecondes, critères de frontière et précision.</td></tr><tr><td>Segmentation linguistique</td><td>Des énoncés, mots et éventuellement morphèmes.</td><td>Ce qui compte comme unité(s)</td></tr><tr><td>Glose</td><td>Une indication lexicale ou grammaticale attachée à une unité.</td><td>Langue des gloses, abréviations et segmentation retenue. Exemple de formalisme : ${ref('leipzig','Leipzig Glossing Rules')}.</td></tr><tr><td>Traduction</td><td>Le sens d’un énoncé dans une autre langue.</td><td>Choix en contexte, ambiguïtés, auteur et révisions.</td></tr></tbody></table></div>
 
 
 </section>
 <section class="lesson-section" id="c2-pangloss"><div class="section-kicker">04 / EXAMINER UNE RESSOURCE RÉELLE</div><h2>Écouter le iaai.<br>Lire ses annotations.</h2><p>${ref('pangloss','Ouvrir le récit et ses annotations sur Pangloss')}</p></section>
 <section class="lesson-section" id="c2-outils"><div class="section-kicker">05 / CHOISIR UN OUTIL POUR UN OBJECTIF</div><h2>De l’enregistrement à l’analyse.<br><em>Outils logiciels.</em></h2><div class="c2-tool-objectives">${toolObjectives2.map((objective,i)=>`<section class="c2-tool-objective" aria-labelledby="c2-objective-${objective.id}">${tag('Objectif '+(i+1))}<h3 id="c2-objective-${objective.id}">${objective.title}</h3><ul class="c2-software-list">${objective.tools.map(tool=>`<li>${ref(tool.ref,tool.name)}<p>${tool.description}</p></li>`).join('')}</ul></section>`).join('')}</div></section>
 <section class="lesson-section" id="c2-transmettre"><div class="section-kicker">06 / CONSERVER LES RELATIONS</div><h2>Transmettre un corpus,<br>avec ses choix d’analyse.</h2><p>Un dossier réutilisable rassemble le média, les annotations, la notice de collecte, les conventions, les versions et les conditions d’accès. Dès la collecte, prévoir qui en sera responsable, où il sera conservé et comment les participants pourront en recevoir une copie. Un dépôt en archive peut prévoir un accès restreint ; le site du cours est un moyen de diffusion.</p><ul><li><strong>Identifiants et métadonnées :</strong> relier média, segments et unités par des identifiants stables. Relever langue ou variété, participants et rôles, lieu, contexte, matériel et réglages ; distinguer dates d’enregistrement, de numérisation et d’annotation. ${ref('paradisec-data','Guide PARADISEC')}</li><li><strong>Conventions et versions :</strong> préciser écriture, unités temporelles, locuteurs, gloses et incertitudes. Dater et attribuer les annotations, conserver l’historique des corrections et relier chaque dérivé à son original.</li><li><strong>Formats et vérification :</strong> conserver le projet natif et un export documenté adapté aux annotations, par exemple EAF, TextGrid ou XML, avec les textes en Unicode. Rouvrir l’export avec le média et vérifier temps, caractères, pistes et liens ; un PDF seul ne conserve pas toutes ces relations. ${ref('paradisec-formats','Formats de dépôt')}</li><li><strong>Usages :</strong> vérifier la notice de chaque ressource. Dans l’exemple Pangloss, le son est sous CC BY-NC-ND 2.5 et les annotations sous CC BY-NC-SA 2.5. Conserver les preuves de consentement et les coordonnées dans un espace à accès limité, séparé des fichiers diffusés.</li></ul>
 <p><strong>Sauvegarder :</strong> appliquer le repère 3–2–1 : trois copies au total, sur deux types de supports, dont une dans un autre lieu. Vérifier régulièrement qu’une sauvegarde peut être restaurée. Adapter les accès à la sensibilité des données ; plusieurs dossiers sur le même disque ne protègent pas d’une panne de ce disque. ${ref('backup','Stockage et sauvegarde des données de recherche')}</p>
 ${callout('CARE : des responsabilités envers les communautés','Les principes CARE concernent la gouvernance des données autochtones : bénéfice collectif, autorité de contrôle, responsabilité et éthique. Ils invitent à convenir avec les communautés concernées des bénéfices attendus, des personnes habilitées à décider, de la restitution et des usages acceptables. L’accord individuel ne remplace pas les décisions collectives pertinentes. Ces engagements se réexaminent au fil du projet. '+ref('care','Principes CARE · GIDA'))}
 <p><strong>Avant diffusion :</strong> faire relire ou réécouter la version prévue par les personnes concernées, vérifier les passages sensibles, les crédits et les accords, puis joindre la licence appropriée. Donner aux participants une copie utilisable et un contact pour les demandes ultérieures. ${ref('johnson-archive','Documentation linguistique et archivage')}</p>
 <p class="lesson-takeaway">Numériser rend un signal manipulable. Annoter rend explicites des unités, des relations et des analyses que l’on peut examiner et réviser.</p><div class="actions">${btn('Commencer l’atelier collectif','#/atelier/2')}${btn('Ouvrir le laboratoire','#/laboratoire/2',true)}${btn('Poursuivre au chapitre 3','#/chapitre/3',true)}</div></section>
 <section class="lesson-section" id="c2-sources">${tag('Références du chapitre')}<h2>Retrouver les sources<br>et leurs annotations.</h2><p>Le corpus, ses fichiers, les références sur la diarisation et les gloses et les guides de bonnes pratiques ci-dessous ont été vérifiés le 9 novembre 2026. Les références sur pyannote.audio, le Speech-to-Text et l’étude sur le marquisien ont été consultées le 12 novembre 2026. Les sites d’Audacity et de PRAAT ont été consultés le 9 novembre 2026 ; les références d’ELAN, FLEX, PLAID et DIG4EL proviennent de la préparation du 6 novembre 2026. Le son et les annotations de l’exemple sont disponibles localement ; les liens externes nécessitent Internet.</p>${sourcesList()}</section></article>`;
}

export function labTwoPage(){activeLab='pangloss';return `<main id="main" class="standalone" tabindex="-1"><div class="page-heading">${tag('Laboratoire / Chapitre 02')}<h1>Écouter. Découper.<br><em>Relier.</em></h1><p>Un récit réel en iaai, avec son audio et ses annotations Pangloss, puis quatre manipulations complémentaires en français. Ces dernières utilisent des exemples fictifs et illustrent des principes d’annotation.</p></div><div id="c2-lab">${labMarkup()}</div><div class="actions">${btn('Revenir au chapitre 2','#/chapitre/2',true)}${btn('Passer à l’atelier','#/atelier/2')}</div></main>`;}
function labMarkup(){return `<div class="labs c2-labs"><div class="tab-bar" role="group" aria-label="Démonstrations du chapitre 2">${[['pangloss','01','Récit réel · Iaai'],['temps','02','Temps · ELAN'],['lexique','03','Lexique · FLEx'],['texte','04','Révision · PLAID'],['preuves','05','Sources · DIG4EL']].map(([id,n,label])=>`<button data-c2-lab="${id}" aria-pressed="${activeLab===id}"><span>${n}</span>${label}</button>`).join('')}</div><div class="lab-body"><p class="small">${activeLab==='pangloss'?'Source publiée : les annotations ci-dessous sont celles de l’archive. Les commentaires du cours figurent en dehors des encadrés.':'Ces exemples français sont fictifs. Les manipulations restent en mémoire jusqu’au rechargement ; exportez les résultats que vous souhaitez conserver.'}</p>${activeLab==='pangloss'?panglossReader():activeLab==='temps'?timeDemo():activeLab==='lexique'?lexiconDemo():activeLab==='texte'?textDemo():evidenceDemo()}</div></div>`;}
function timeDemo(){return `<div class="lab-intro">${tag('Principe : l’annotation temporelle')}<h3>La transcription occupe un intervalle.</h3><p>Écoutez le média, choisissez une annotation et modifiez ses bornes ou sa piste. Une transcription et un commentaire peuvent décrire le même intervalle sans être confondus.</p></div>${audioEditor('demo')}<div class="lab-explanation"><b>Une piste a une fonction explicite.</b><p>ELAN permet aussi des relations hiérarchiques entre annotations. Ce démonstrateur se limite à des pistes indépendantes. Les exports EAF conservent ces pistes et leurs temps ; le CSV conserve en plus le nom saisi pour l’auteur.</p></div>`;}
function audioEditor(scope){return `<div class="c2-audio-editor" data-editor="${scope}"><div class="source-frame"><span class="source-label">${scope==='demo'?'Exemple complémentaire D2-01 · voix de synthèse':'Source réelle · Taï Waheo · iaai'}</span><audio id="c2-audio" controls preload="metadata" src="${scope==='demo'?asset+'demo-voix.wav':panglossAsset+'144254_HULUP_44k.mp3'}">Votre navigateur ne peut pas lire cet audio.</audio><svg id="c2-wave" viewBox="0 0 900 100" role="img" aria-label="${scope==='demo'?'Amplitude du son':'Frise des segments de la source Pangloss, sans représentation de l’amplitude'} ; la zone colorée indique votre intervalle"></svg><div class="c2-time-line"><span>0 s</span><output id="c2-position">Chargement du média…</output><span id="c2-duration"></span></div></div><p class="small c2-audio-credit">${scope==='demo'?'Texte inventé, lu par la voix de synthèse Thomas. Aucun témoignage réel n’est reproduit.':panglossCredit()}</p><p class="small">${scope==='demo'?'Les trois annotations initiales appartiennent à l’exemple expliqué.':'Votre table d’annotations est vide au départ. Créez vos propres segments après l’écoute.'} Les temps sont exprimés en secondes depuis le début du fichier.</p><form id="c2-segment-form"><div class="c2-segment-controls"><div><label class="field-label" for="c2-start">Début (s)</label><input id="c2-start" type="number" min="0" step="0.001" value="0" required><button type="button" class="text-link" data-c2-action="mark-start">Prendre le temps de lecture</button></div><div><label class="field-label" for="c2-end">Fin (s)</label><input id="c2-end" type="number" min="0" step="0.001" value="2" required><button type="button" class="text-link" data-c2-action="mark-end">Prendre le temps de lecture</button></div><div><label class="field-label" for="c2-tier">Piste</label><select id="c2-tier"><option>Transcription</option><option>Locuteur</option><option>Traduction</option><option>Glose</option><option>Commentaire</option><option>Reformulation</option></select></div></div><label class="field-label" for="c2-annotation-text">Contenu de l’annotation</label><textarea id="c2-annotation-text" rows="2" required placeholder="Saisissez votre annotation sur la piste choisie."></textarea><label class="field-label" for="c2-author">Auteur de l’annotation ou identifiant du groupe</label><input class="text-input" id="c2-author" maxlength="80" placeholder="Un pseudonyme ou un identifiant suffit."><div class="actions"><button class="button" id="c2-save-segment" type="submit">Ajouter l’annotation</button><button class="button secondary" type="button" data-c2-action="play-selection">Écouter l’intervalle</button><button class="text-link" type="button" data-c2-action="new-segment">Nouvelle annotation</button></div><p id="c2-segment-status" class="small" role="status"></p></form><div id="c2-annotation-list"></div><div class="actions"><button class="button secondary" data-c2-action="export-csv">Exporter les annotations · CSV ↓</button><button class="button secondary" data-c2-action="export-eaf">Exporter pour ELAN · EAF ↓</button><a class="text-link" href="${scope==='demo'?asset+'demo-voix.wav':panglossAsset+'144254_HULUP_44k.mp3'}" download>Télécharger le média ↓</a></div><p class="small">Pour ouvrir l’EAF dans ELAN, placez-le dans le même dossier que le média téléchargé, en conservant son nom. Cet export utilise des pistes temporelles indépendantes ; il ne reconstitue pas la hiérarchie énoncé–mot–glose du XML Pangloss. Pour une glose, citez l’unité source dans le contenu ; ne présentez pas les bornes de son énoncé comme un minutage du mot. Les chevauchements sont possibles entre pistes, mais pas sur une même piste. Pour deux paroles simultanées, créez des pistes distinctes dans le projet ELAN.</p></div>`;}
function lexiconDemo(){return `<div class="lab-intro">${tag('Principe : texte interlinéaire et lexique')}<h3>Deux occurrences, une entrée lexicale.</h3><p>Modifiez la glose de l’entrée LEX-01. Observez les deux occurrences reliées à cette entrée ; la forme source reste inchangée.</p></div><div class="source-frame"><span class="source-label">Exemples écrits fictifs D2-02</span><blockquote class="source-body">Le poisson revient.\nLes poissons reviennent.</blockquote></div><div class="c2-two"><div class="c2-panel"><span class="mini-label">Entrée LEX-01 · exemple d’analyse</span><h3>poisson</h3><p>Catégorie : nom. Sens retenu : animal aquatique.</p><label class="field-label" for="c2-gloss">Glose de la base</label><input class="text-input" id="c2-gloss" maxlength="80" value="${esc(lexicalGloss)}"><p class="small">Une glose est une aide au sens, souvent courte. Ici, elle est en français pour faciliter la manipulation.</p></div><div class="c2-panel"><span class="mini-label">Occurrences liées</span><div id="c2-interlinear">${interlinear()}</div></div></div><div class="actions"><button class="button secondary" data-c2-action="export-lexicon">Exporter ce petit lexique · CSV ↓</button></div><div class="lab-explanation"><b>La propagation dépend d’un lien, pas d’une ressemblance.</b><p>Les deux occurrences ont été reliées à LEX-01 dans cette démonstration. Dans un projet réel, vérifiez le sens avant de réutiliser une entrée. FLEx gère des analyses plus riches ; ce CSV pédagogique ne constitue pas un projet FLEx ou un fichier LIFT.</p></div>`;}
function interlinear(){return `<dl class="c2-interlinear"><dt>Forme</dt><dd>poisson</dd><dt>Segmentation</dt><dd>poisson</dd><dt>Glose</dt><dd>${esc(lexicalGloss)||'—'}</dd></dl><dl class="c2-interlinear"><dt>Forme</dt><dd>poissons</dd><dt>Segmentation</dt><dd>poisson-s</dd><dt>Glose</dt><dd>${esc(lexicalGloss)||'—'}-PL</dd></dl><p class="small">PL = pluriel. Segmentation écrite simplifiée, distincte d’une transcription phonétique.</p>`;}
function textDemo(){return `<div class="lab-intro">${tag('Principe : catégories et annotations partagées')}<h3>Une même source, plusieurs lectures.</h3><p>Cliquez sur le premier puis le dernier mot d’un passage. Attribuez une catégorie et un auteur A ou B. Pour annoter un seul mot, cliquez deux fois sur ce mot.</p></div><div class="source-frame"><span class="source-label">Document fictif D2-03 · les boutons reprennent le texte source</span><div class="c2-tokens" aria-label="Mots du document">${tokens.map(t=>`<button data-c2-token="${t.id}" aria-pressed="false">${esc(t.text)}</button>`).join(' ')}</div></div><p id="c2-selection" role="status">Aucun passage sélectionné.</p><div class="c2-segment-controls"><div><label class="field-label" for="c2-category">Catégorie</label><select id="c2-category"><option>Lieu</option><option>Repère temporel</option><option>Activité</option><option>Incertain</option></select></div><div><label class="field-label" for="c2-annotator">Auteur</label><select id="c2-annotator"><option ${currentAuthor==='A'?'selected':''}>A</option><option ${currentAuthor==='B'?'selected':''}>B</option></select></div></div><label class="field-label" for="c2-rationale">Justification ou difficulté</label><input class="text-input" id="c2-rationale" maxlength="300"><div class="actions"><button class="button" data-c2-action="add-text-annotation">Ajouter cette lecture</button><button class="button secondary" data-c2-action="export-text">Exporter les lectures · JSON ↓</button></div><div id="c2-text-list">${textList()}</div><div class="lab-explanation"><b>Un désaccord ouvre une discussion.</b><p>La comparaison ci-dessus signale les catégories différentes attribuées exactement au même passage. Elle ne choisit aucune réponse. Les frontières peuvent aussi différer : revenez alors aux conventions. Cette simulation A/B se déroule sur un seul appareil ; elle n’établit pas de connexion à PLAID.</p></div>`;}
function textList(){if(!textAnnotations.length)return '<p class="small">Aucune lecture enregistrée dans cette démonstration.</p>';return `<ul class="c2-reads">${textAnnotations.map((a,i)=>{const conflict=textAnnotations.some(b=>b.start===a.start&&b.end===a.end&&b.category!==a.category);return `<li><span class="badge">${esc(a.author)} · ${esc(a.category)}</span><q>${esc(writtenDemo.slice(a.start,a.end))}</q><p>${esc(a.rationale)||'Justification non renseignée.'}</p>${conflict?'<span class="c2-disagreement">Catégories différentes pour ce passage : à discuter.</span>':''}<button class="text-link" data-c2-delete-text="${i}">Retirer cette lecture</button></li>`;}).join('')}</ul>`;}
function evidenceDemo(){return `<div class="lab-intro">${tag('Principe : sources, concepts et hypothèses')}<h3>Avec quels appuis formulez-vous une hypothèse ?</h3><p>Sélectionnez les pièces à mettre en regard. Notez ce qu’elles permettent d’étudier et ce qui manque encore. Cette maquette de dossier n’exécute ni inférence bayésienne ni LLM.</p></div><div class="c2-concept-demo"><div class="source-frame"><span class="source-label">Exemple écrit fictif P1</span><blockquote class="source-body">Je ne viens pas.</blockquote></div><p>Reliez chaque forme à un concept. Plusieurs formes peuvent contribuer au même concept ; ce choix reste une annotation à justifier.</p><div class="c2-concepts">${conceptWords.map((word,i)=>`<div><label class="field-label" for="c2-concept-${i}">${word}</label><select id="c2-concept-${i}" data-c2-concept="${i}">${conceptChoices.map(value=>`<option ${conceptLinks[i]===value?'selected':''}>${value}</option>`).join('')}</select></div>`).join('')}</div><p id="c2-concept-summary" class="small" aria-live="polite">${conceptSummary()}</p></div><div class="c2-evidence">${evidence.map(e=>`<label class="c2-evidence-card"><input type="checkbox" data-c2-evidence="${e.id}" ${evidenceIds.has(e.id)?'checked':''}><span><b>${e.id} · ${e.type}</b><span>${e.text}</span></span></label>`).join('')}</div><div id="c2-evidence-summary" class="callout" aria-live="polite">${evidenceSummary()}</div><label class="field-label" for="c2-hypothesis">Votre hypothèse, ses appuis et ses limites</label><textarea id="c2-hypothesis" rows="4" placeholder="Citez les identifiants des pièces retenues et indiquez ce qu’il faudrait encore observer.">${esc(hypothesis)}</textarea><div class="actions"><button class="button secondary" data-c2-action="export-evidence">Exporter mon dossier · .md ↓</button></div><div class="lab-explanation"><b>Une généralisation demande plus qu’un exemple.</b><p>DIG4EL relie notamment des formes à des concepts dans des questionnaires contextualisés. Les données typologiques apportent un autre type d’appui. Garder les sources distinctes permet d’examiner une proposition avant d’en faire une ressource pédagogique. ${ref('dig4el')}</p></div>`;}
function conceptSummary(){return conceptWords.map((word,i)=>esc(word)+' → '+esc(conceptLinks[i])).join(' · ');}
function evidenceSummary(){const selected=evidence.filter(e=>evidenceIds.has(e.id));return `<span class="callout-label">Composition du dossier</span><p>${selected.filter(e=>e.kind==='example').length} exemple(s) · ${selected.filter(e=>e.kind==='reference').length} description · ${selected.filter(e=>e.kind==='typology').length} question typologique.</p><p>${selected.length?'Pièces retenues : '+selected.map(e=>e.id).join(', ')+'.':'Aucune pièce retenue.'} Ce décompte décrit votre sélection ; il ne mesure pas la fiabilité d’une hypothèse.</p>`;}

export function workshopTwo(){return `<main id="main" class="standalone workshop chapter-two c2-live-workshop" tabindex="-1">
 <div class="page-heading">${tag('Atelier 02 / Mise en situation collective')}<h1>De l’enregistrement<br><em>à l’analyse.</em></h1><p>Un étudiant enregistre un autre étudiant. Le groupe parcourt ensemble toute la chaîne : préparer la collecte, enregistrer, documenter, puis annoter la parole. Chacun peut suivre les manipulations sur son ordinateur.</p><div class="actions"><button class="button secondary" data-action="print">Imprimer les consignes</button></div></div>
 <section class="lesson-section" id="a2-contexte"><div class="section-kicker">01 / LE CONTEXTE</div><h2>Une minute pour raconter la matinée.</h2><p>Enregistrer un résumé en une minute de la matinée jusque-là, à des fins de documentation du Master. Le résultat pourra être inclus sur le site internet du cours, selon l’accord donné par la personne enregistrée.</p><p>Un étudiant prend la parole, un autre réalise l’enregistrement. Le reste du groupe observe et contribue aux choix. Annoncer la consigne, la langue utilisée et les destinataires du document.</p></section>
 <section class="lesson-section" id="a2-consentement"><div class="section-kicker">02 / LE CONSENTEMENT ÉCLAIRÉ</div><h2>Expliquer les usages. Recueillir un accord oral.</h2><p>Présenter le projet dans une langue comprise par la personne et vérifier ce qu’elle a compris. Préciser qui conserve l’audio et les annotations, où, pour combien de temps, qui y accède et qui contacter pour retirer son consentement. La participation est volontaire : refuser n’a pas de conséquence sur l’évaluation ; un autre rôle dans l’atelier reste possible. ${ref('cnil-consent','Repères de la CNIL')}</p>
 ${callout('Exemple de dialogue après présentation des informations','« Nous te proposons de raconter en une minute ta matinée pour documenter le Master. Nous allons écouter et annoter cet enregistrement ensemble. Es-tu d’accord pour être enregistré et pour que le groupe travaille sur ta voix ? Acceptes-tu aussi que le résultat soit publié sur le site internet du cours, accessible au public ? Sous quel nom ou pseudonyme souhaites-tu apparaître ? Tu peux refuser ou demander l’arrêt de la prise. »')}
 <p>Recueillir une réponse distincte pour le travail en classe, la publication et un éventuel dépôt en archive. Confirmer les réutilisations acceptées après le choix de la licence. Si la situation rend difficile l’utilisation d’un formulaire papier, le consentement peut aussi être recueilli verbalement sur l’enregistrement même, avec l’accord préalable de la personne pour l’enregistrer. Il doit être aussi détaillé à l’oral qu’à l’écrit : conserver les explications et les réponses, leur date et le lien avec la prise concernée. ${ref('johnson-archive','Recueillir et archiver les accords')}</p>
 <p>Conserver cette preuve dans un espace à accès limité. Si elle figure dans le même fichier que le récit, préparer une copie destinée au groupe ou au public qui exclut cette séquence et documenter la coupe. Un pseudonyme ne rend pas la voix anonyme : le contenu et la voix peuvent permettre de reconnaître la personne. ${ref('corinte','Protection des personnes dans les corpus oraux')}</p>
 <details open><summary>Garder CARE en tête : quatre questions à aborder</summary><p>CARE concerne la gouvernance des données autochtones. Avec les personnes et, le cas échéant, les communautés concernées, préciser les engagements et vérifier leur mise en œuvre :</p><ul><li><strong>Bénéfice collectif :</strong> à qui le travail sera-t-il utile et comment restituer les résultats ?</li><li><strong>Autorité de contrôle :</strong> qui peut décider de l’accès et des réutilisations ?</li><li><strong>Responsabilité :</strong> qui entretient le dialogue, conserve les données et rend compte des usages ?</li><li><strong>Éthique :</strong> quels risques, attentes ou restrictions culturelles faut-il prendre en compte ?</li></ul><p>${ref('care','Principes CARE · GIDA')}</p></details></section>
 <section class="lesson-section" id="a2-licence"><div class="section-kicker">03 / LA LICENCE</div><h2>Choisir les conditions de réutilisation.</h2><p>Identifier les titulaires des droits sur le son, le récit et les annotations, puis choisir avec eux les réutilisations permises : attribution, modifications, usages commerciaux, partage sous la même licence. Le ${link('sélecteur de licences Creative Commons','https://creativecommons.org/chooser/')} aide à examiner les options. Si une diffusion sous licence publique ne convient pas, consigner un accès restreint et les autorisations accordées.</p><p>Noter le nom complet de la licence, sa version, son lien, les crédits et les fichiers concernés. Les autorisations de droit d’auteur accordées sous Creative Commons ne sont pas révocables tant que ses conditions sont respectées. Cela ne supprime pas les droits relatifs aux données personnelles ni la possibilité de retirer le consentement aux traitements qui reposent sur lui. Expliquer avant publication qu’une suppression du site ne garantit pas la disparition des copies déjà diffusées. ${ref('cc-licences','Licences, droits et limites · Creative Commons')}</p></section>
 <section class="lesson-section" id="a2-parametres"><div class="section-kicker">04 / LES CHOIX TECHNIQUES</div><h2>Choisir les paramètres du fichier audio.</h2><p>Pour cette nouvelle prise, viser <strong>WAV PCM, 48 kHz, 24 bits</strong> si l’appareil le permet ; relever tout autre réglage utilisé. C’est un choix pratique pour l’atelier : les exigences de l’archive destinataire sont à vérifier avant une collecte. PARADISEC vise notamment 96 kHz / 24 bits pour l’archivage. ${ref('paradisec-formats','Recommandations de prise de son et de dépôt')}</p><p>Choisir le nombre de canaux selon les microphones : un canal mono peut contenir plusieurs voix. Vérifier le format réellement produit par l’enregistreur et conserver l’original. Convertir un MP3 en WAV ou augmenter sa fréquence après coup ne restaure pas la qualité perdue. Les traitements de réduction de bruit ou de normalisation se font sur une copie et se documentent.</p></section>
 <section class="lesson-section" id="a2-verification"><div class="section-kicker">05 / LA VÉRIFICATION TECHNIQUE</div><h2>L’enregistreur est-il prêt ?</h2><ul><li>Vérifier la batterie, l’espace disponible, le microphone sélectionné et le branchement du casque.</li><li>Installer le microphone et limiter les frottements et les bruits parasites.</li><li>Faire un bref essai incluant les passages les plus forts, ajuster le gain d’entrée et garder une marge sous 0 dBFS : des crêtes vers −6 dBFS constituent un repère dans Audacity. Le volume du casque ne règle pas le niveau enregistré.</li><li>Réécouter l’essai au casque avant de commencer la prise définitive, puis surveiller le son pendant l’enregistrement.</li></ul><p>${link('Faire un enregistrement test · Audacity','https://manual.audacityteam.org/man/tutorial_making_a_test_recording.html')}</p></section>
 <section class="lesson-section" id="a2-metadonnees"><div class="section-kicker">06 / L’ENREGISTREMENT ET SES MÉTADONNÉES</div><h2>Enregistrer le récit et documenter la prise.</h2><p>Lancer l’enregistrement, vérifier qu’il a bien démarré et annoncer un identifiant de prise et la date. Laisser ensuite l’étudiant raconter sa matinée pendant environ une minute. Rester à son écoute. À la fin, arrêter et sauvegarder la prise.</p><p>Conserver une notice reliée au fichier par un identifiant stable, par exemple <code>A02_20261109_01</code> pour une prise du 9 novembre 2026. Noter les informations pendant la collecte :</p><dl class="metadata"><dt>Date et heure</dt><dd>Date, heure de début et fuseau horaire.</dd><dt>Lieu</dt><dd>Lieu de la séance et conditions sonores.</dd><dt>Participants</dt><dd>Identifiants des participants, rôles, langue ou variété et langue de traduction ; ajouter ensuite les auteurs des annotations.</dd><dt>Contexte</dt><dd>Résumé de la matinée pour documenter le Master ; consigne donnée.</dd><dt>Faits marquants</dt><dd>Interruptions, bruit, hésitation, changement de microphone ou reprise éventuelle.</dd><dt>Fichier et réglages</dt><dd>Nom du fichier, durée, appareil, microphone, fréquence, profondeur en bits, format et canaux.</dd><dt>Accords et licence</dt><dd>Référence du consentement, usages acceptés, licence et attribution retenues ; accès et durée de conservation.</dd></dl><p>Conserver les coordonnées et les informations sensibles séparément des métadonnées publiques. ${ref('paradisec-data','Organiser les données et les métadonnées · PARADISEC')}</p></section>
 <section class="lesson-section" id="a2-ecoute"><div class="section-kicker">07 / L’OUVERTURE SUR ORDINATEUR</div><h2>Vérifier la qualité de l’enregistrement.</h2><p>Copier le fichier sur un ordinateur sans effacer tout de suite la carte de l’enregistreur. Pour cette prise d’une minute, écouter <strong>l’intégralité</strong> au casque et vérifier les paramètres du fichier. Si elle est inutilisable, la refaire tant que les participants sont sur place.</p><p>Après vérification des copies, conserver l’original intact et préparer une copie de travail conforme aux accords, sans la séquence de consentement ni les informations exclues du partage. Chaque étudiant peut l’ouvrir sur son ordinateur. Noter toute coupe et les décalages temporels ; toutes les annotations du groupe doivent se rapporter à la même version du média.</p><p>Organiser dès maintenant trois copies sur deux types de supports, dont une dans un autre lieu, avec des accès adaptés. Vérifier qu’une sauvegarde se rouvre correctement. Les copies de travail des étudiants ne remplacent pas une sauvegarde organisée. ${ref('backup','Repère 3–2–1 et stockage')}</p></section>
 <section class="lesson-section" id="a2-transcription"><div class="section-kicker">08 / DIARISATION, TRANSCRIPTION, TRADUCTION</div><h2>Relier des annotations au signal.</h2><p>Ouvrir la copie de travail dans ${ref('audacity','Audacity')}, ${ref('praat','PRAAT')} ou ${ref('elan','ELAN')}. Utiliser des étiquettes ou des pistes distinctes selon le logiciel.</p><ol><li><strong>Diarisation manuelle :</strong> repérer qui parle quand, avec des identifiants de locuteurs et des bornes temporelles. Relever les éventuelles interventions de l’étudiant qui enregistre.</li><li><strong>Transcription :</strong> écrire ce qui est prononcé, segment par segment ; convenir du traitement des hésitations et des passages inaudibles.</li><li><strong>Traduction :</strong> choisir une langue cible connue du groupe et traduire les énoncés sur une couche distincte.</li></ol><p>Réécouter les segments et relire ensemble la transcription et la traduction avec une personne compétente dans la langue. Dater et attribuer les corrections, signaler ce qui reste incertain. Sauvegarder le projet et les annotations : étiquettes TXT pour Audacity, TextGrid pour PRAAT, EAF pour ELAN. Rouvrir ces fichiers avec le média et vérifier les bornes et les caractères.</p></section>
 <section class="lesson-section" id="a2-plaid"><div class="section-kicker">09 / GLOSES, LEXIQUE ET ANALYSE AVEC PLAID</div><h2>Passer de la transcription à l’analyse.</h2><p>Avant tout transfert vers une instance de PLAID en ligne, vérifier qui l’héberge, qui accède au projet et si cet usage est couvert par les accords recueillis. Reprendre ensuite quelques énoncés de la transcription pour montrer trois opérations :</p><ol><li><strong>Glose IGT :</strong> construire un texte interlinéaire glosé, avec les formes, une segmentation justifiée par l’analyse, les gloses et une traduction libre. Définir les abréviations retenues.</li><li><strong>Lexique :</strong> créer une entrée à partir d’une forme rencontrée et la relier à ses occurrences dans le texte.</li><li><strong>Analyse :</strong> examiner une forme, sa catégorie et sa fonction en contexte ; comparer les propositions du groupe.</li></ol><p>Faire discuter les analyses par des personnes compétentes dans la langue et conserver les incertitudes. Exporter le projet, le lexique et les liens avec les exemples dans les formats documentés par l’outil, puis vérifier leur réouverture. ${ref('plaid-igt','Guide de l’éditeur IGT de PLAID')}</p><p><strong>Clore la collecte :</strong> restituer une copie au participant et lui faire réécouter ou relire la version destinée au site. Vérifier les passages sensibles, les crédits et l’accord de diffusion ; conserver média, métadonnées, annotations et licence dans le dossier final.</p></section>
 <section class="lesson-section" id="a2-dig4el"><div class="section-kicker">DÉMONSTRATION SÉPARÉE / DIG4EL</div><h2>Deviner la grammaire au travers des productions.</h2><p>L’enseignant présente DIG4EL à partir d’un jeu d’exemples préparé pour la démonstration : observer les productions annotées, examiner une hypothèse grammaticale et revenir aux exemples qui l’appuient.</p><p>Discuter ce que les données permettent de proposer et ce qui reste à vérifier. ${ref('dig4el','Présentation et documentation de DIG4EL')}</p></section>
 <div class="actions">${btn('Revenir au chapitre 2','#/chapitre/2',true)}</div></main>`;}

const slides2=[
 ['NUMÉRISER LES PRODUCTIONS LINGUISTIQUES','De la parole<br>au corpus annoté.','Une situation humaine → un signal numérique → des unités et des analyses.'],
 ['ENREGISTRER','Une voix, un dispositif,<br>une situation.','Microphone, niveau, échantillonnage, canaux.<br>Fichier de conservation et copie de consultation.<br>Accords, contexte, métadonnées et sauvegardes.'],
 ['DIARISATION','Qui parle quand ?','Segmentation et regroupement en locuteurs.<br>LOC_01 et LOC_02 peuvent se chevaucher.<br><br>Repérer une voix, connaître son nom et transcrire ses paroles sont trois tâches distinctes.'],
 ['TRANSCRIRE ET ALIGNER','Des formes écrites.<br>Des bornes temporelles.','Une convention d’écriture et une unité de segmentation.<br>Une transcription relue à l’écoute.<br>Une trace des corrections et des incertitudes.'],
 ['GLOSER ET TRADUIRE','Une unité, une glose.<br>Un énoncé, une traduction.','Forme → mot → morphème, selon l’analyse disponible.<br>La glose indique un sens ou une fonction.<br>La traduction restitue le sens en contexte.'],
 ['CORPUS RÉEL / PANGLOSS','L’origine du kong Hulup.','', 'pangloss'],
 ['LIRE LA STRUCTURE','23 segments.<br>229 unités W.','Le XML relie chaque segment au temps.<br>Les mots sont reliés à des gloses, sans minutage propre.<br>Un seul locuteur est crédité ; aucune piste de diarisation n’est fournie.'],
 ['LES OUTILS','ELAN · FLEx<br>PLAID · DIG4EL','Temps et pistes · texte et lexique.<br>Révision partagée · exemples et description.<br><br>Pangloss diffuse le corpus ; COCOON conserve les ressources.'],
 ['MANIPULATION COMPLÉMENTAIRE','Créer une annotation<br>temporelle.','', 'temps'],
 ['TRANSMETTRE','Conserver les relations<br>et la provenance.','Média + annotations + conventions + notices.<br>Versions, auteurs, identifiants et licences.<br>Rouvrir les exports et vérifier les caractères et les temps.'],
 ['ATELIER / MISE EN SITUATION COLLECTIVE','Enregistrer, annoter,<br>analyser.','Un étudiant enregistre le résumé de la matinée par un autre.<br>Contexte, consentement oral, licence, réglages et métadonnées.<br>Diarisation, transcription, traduction, puis gloses et lexique avec PLAID.<br><br>Démonstration séparée de DIG4EL.']
];
export function projectionTwo(index=0){const i=Math.max(0,Math.min(slides2.length-1,Number(index)||0)),s=slides2[i];if(s[3])activeLab=s[3];return `<div class="presentation-shell"><header class="presentation-header"><a href="#/chapitre/2">← Revenir au chapitre 2</a><span>HUMANITÉS NUMÉRIQUES / CHAPITRE 02</span><button class="text-link" data-action="fullscreen">Plein écran ⛶</button></header><main id="main" tabindex="-1" class="slide ${s[3]?'interactive-slide':''}"><div class="slide-heading">${tag(s[0])}<h1>${s[1]}</h1></div>${s[3]?`<div id="c2-lab">${s[3]==='pangloss'?panglossReader(true):labMarkup()}</div>`:`<div class="slide-content"><p>${s[2]}</p></div>`}</main><footer class="presentation-footer"><div class="slide-controls"><button class="button secondary" data-c2-slide="${i-1}" ${i===0?'disabled':''} aria-label="Diapositive précédente">←</button><span class="mono">${i+1} / ${slides2.length}</span><button class="button" data-c2-slide="${i+1}" ${i===slides2.length-1?'disabled':''} aria-label="Diapositive suivante">→</button></div>${i===slides2.length-1?btn('Ouvrir l’atelier','#/atelier/2',true):'<span class="small">← → pour naviguer · Échap pour quitter</span>'}</footer></div>`;}

export function bindChapterTwo({signal,notify,download}) {
 const opts={signal};
 function centerLabTab(){const selected=document.querySelector('[data-c2-lab][aria-pressed="true"]');if(!selected)return;const bar=selected.parentElement;bar.scrollLeft+=selected.getBoundingClientRect().left-bar.getBoundingClientRect().left-(bar.clientWidth-selected.offsetWidth)/2;}
 const scope=()=>document.querySelector('[data-editor]')?.dataset.editor;
 const rows=()=>scope()==='workshop'?workbook.segments:demoSegments;
 const setRows=value=>{if(scope()==='workshop'){workbook.segments=value;persist();}else demoSegments=value;};
 const status=text=>{const element=document.querySelector('#c2-segment-status');if(element)element.textContent=text;};
 const persist=()=>{const saved=saveLocal(storedKey,workbook);const element=document.querySelector('#c2-save-status');if(element)element.textContent=saved?'Carnet et annotations enregistrés dans ce navigateur. Pensez à les exporter.':'Stockage indisponible : exportez votre travail avant de quitter cette page.';if(!saved)notify('Stockage indisponible. Exportez une sauvegarde JSON pour conserver votre travail.');};
 let stopAt=null;
 function resetEditor(){selectedAnnotation=null;const form=document.querySelector('#c2-segment-form');if(form)form.reset();const button=document.querySelector('#c2-save-segment');if(button)button.textContent='Ajouter l’annotation';status('Nouvelle annotation.');drawWave();}
 function formSegment(){return {id:selectedAnnotation||`s${Date.now()}-${Math.random().toString(36).slice(2,6)}`,start:document.querySelector('#c2-start').valueAsNumber,end:document.querySelector('#c2-end').valueAsNumber,tier:document.querySelector('#c2-tier').value,text:document.querySelector('#c2-annotation-text').value,author:document.querySelector('#c2-author').value};}
 function drawWave(){const svg=document.querySelector('#c2-wave');if(!svg)return;const data=mediaData[scope()==='workshop'?'atelier':'demo'];if(!data)return;const width=900, start=Number(document.querySelector('#c2-start')?.value)||0,end=Number(document.querySelector('#c2-end')?.value)||0;const time=document.querySelector('#c2-audio')?.currentTime||0;svg.innerHTML=`<rect x="${Math.max(0,start/data.duration*width)}" y="0" width="${Math.max(0,Math.min(end,data.duration)-start)/data.duration*width}" height="100" fill="#e6ae8028"/>${data.peaks?data.peaks.map((v,i)=>`<path d="M${i/data.peaks.length*width} ${50-v*45}v${v*90}" stroke="#9dc7ba" stroke-width="2"/>`).join(''):data.segments.map((s,i)=>`<rect x="${s.start/data.duration*width}" y="35" width="${(s.end-s.start)/data.duration*width}" height="30" fill="${i%2?'#9dc7ba55':'#9dc7ba99'}" stroke="#0b191d"/>`).join('')}<path d="M${time/data.duration*width} 0v100" stroke="#e6ae80" stroke-width="2"/>`;}
 function renderRows(){const target=document.querySelector('#c2-annotation-list');if(!target)return;const list=rows();target.innerHTML=list.length?`<div class="c2-table-wrap"><table><caption>${list.length} annotation(s) · vos pistes</caption><thead><tr><th>Intervalle (s)</th><th>Piste</th><th>Annotation</th><th>Actions</th></tr></thead><tbody>${[...list].sort((a,b)=>a.start-b.start).map(s=>`<tr><td>${s.start.toLocaleString('fr-FR',{minimumFractionDigits:3})}–${s.end.toLocaleString('fr-FR',{minimumFractionDigits:3})}</td><td>${esc(s.tier)}</td><td>${esc(s.text)}<small class="c2-row-author">${esc(s.author)||'Auteur non renseigné'}</small></td><td><button class="text-link" data-c2-edit="${esc(s.id)}">Modifier</button><button class="text-link" data-c2-delete="${esc(s.id)}">Supprimer</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="c2-empty">Aucune annotation pour cet enregistrement.</p>';}
 async function initAudio(){
  selectedAnnotation=null;stopAt=null;const audio=document.querySelector('#c2-audio');if(!audio)return;
  const name=scope()==='workshop'?'atelier':'demo';
  try{
   if(!mediaData[name]){const response=await fetch(name==='atelier'?panglossAsset+'data.json':asset+'demo-voix.json',{signal});if(!response.ok)throw new Error();mediaData[name]=await response.json();}
   if(signal.aborted||audio!==document.querySelector('#c2-audio'))return;
   if(!loaded&&name==='atelier'){const saved=loadSaved(storedKey,null);if(saved){try{workbook=validateWorkbook(saved,mediaData.atelier.duration);}catch{notify('La sauvegarde locale n’a pas pu être chargée. Vous pouvez importer une sauvegarde JSON.');}}loaded=true;document.querySelectorAll('[data-c2-note]').forEach(el=>el.value=workbook.notes[el.dataset.c2Note]||'');}
   if(name==='demo'&&!mediaData.demo.initialized){demoSegments=mediaData.demo.segments.map(s=>({...s}));mediaData.demo.initialized=true;}
   document.querySelector('#c2-duration').textContent=mediaData[name].duration.toLocaleString('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2})+' s';
   for(const id of ['c2-start','c2-end'])document.getElementById(id).max=mediaData[name].duration;
   document.querySelector('#c2-position').textContent='Lecture : 0,00 s';drawWave();renderRows();
   audio.addEventListener('timeupdate',()=>{if(stopAt!==null&&audio.currentTime>=stopAt){audio.pause();audio.currentTime=stopAt;stopAt=null;}document.querySelector('#c2-position').textContent='Lecture : '+audio.currentTime.toLocaleString('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2})+' s';drawWave();},opts);
   audio.addEventListener('ended',()=>stopAt=null,opts);
   audio.addEventListener('error',()=>status('Le média ne peut pas être lu. Téléchargez-le ou utilisez la variante écrite de l’atelier.'),opts);
  }catch(error){if(error.name!=='AbortError'){status('Chargement du média impossible. Rechargez la page ou téléchargez le dossier.');}}
 }
 function updateSelection(){const [a,b]=selectedWords;const lo=Math.min(a,b??a),hi=Math.max(a,b??a);document.querySelectorAll('[data-c2-token]').forEach(el=>el.setAttribute('aria-pressed',selectedWords.length>0&&Number(el.dataset.c2Token)>=lo&&Number(el.dataset.c2Token)<=hi));document.querySelector('#c2-selection').textContent=selectedWords.length===2?'Passage retenu : « '+writtenDemo.slice(tokens[lo].start,tokens[hi].end)+' »':selectedWords.length?'Choisissez le dernier mot du passage (ou le même mot).':'Aucun passage sélectionné.';}
 document.addEventListener('input',e=>{
  if(e.target.matches('[data-c2-note]')){workbook.notes[e.target.dataset.c2Note]=e.target.value;persist();}
  if(e.target.id==='c2-start'||e.target.id==='c2-end')drawWave();
  if(e.target.id==='c2-gloss'){lexicalGloss=e.target.value;document.querySelector('#c2-interlinear').innerHTML=interlinear();}
  if(e.target.id==='c2-hypothesis')hypothesis=e.target.value;
 },opts);
 document.addEventListener('change',async e=>{
  if(e.target.matches('[data-c2-concept]')){conceptLinks[Number(e.target.dataset.c2Concept)]=e.target.value;document.querySelector('#c2-concept-summary').innerHTML=conceptSummary();}
  if(e.target.matches('[data-c2-evidence]')){const id=e.target.dataset.c2Evidence;e.target.checked?evidenceIds.add(id):evidenceIds.delete(id);document.querySelector('#c2-evidence-summary').innerHTML=evidenceSummary();}
  if(e.target.id==='c2-annotator')currentAuthor=e.target.value;
  if(e.target.id==='c2-import'){
   const file=e.target.files[0];if(!file)return;
   try{if(file.size>1000000)throw new Error();if(!mediaData.atelier)throw new Error();const restored=validateWorkbook(JSON.parse(await file.text()),mediaData.atelier.duration);
    if((workbook.segments.length||Object.values(workbook.notes).some(Boolean))&&!confirm('Remplacer le travail du chapitre 2 ? Exportez d’abord votre sauvegarde actuelle si vous souhaitez la conserver.'))return;
    workbook=restored;persist();document.querySelectorAll('[data-c2-note]').forEach(el=>el.value=workbook.notes[el.dataset.c2Note]||'');resetEditor();renderRows();notify('Carnet et annotations du chapitre 2 repris.');
   }catch{notify('Sauvegarde invalide : utilisez un JSON exporté depuis cet atelier.');}finally{e.target.value='';}
  }
 },opts);
 document.addEventListener('submit',e=>{
  if(e.target.id==='c2-workbook'){e.preventDefault();return;}
  if(e.target.id!=='c2-segment-form')return;e.preventDefault();
  const data=mediaData[scope()==='workshop'?'atelier':'demo'];if(!data){status('Attendez le chargement du média.');return;}
  const row=formSegment(),error=validateSegment(row,data.duration);if(error){status(error);return;}
  if(rows().some(s=>s.id!==row.id&&s.tier===row.tier&&row.start<s.end&&row.end>s.start)){status('Deux annotations se chevauchent sur cette piste. Ajustez les bornes ou choisissez une autre piste.');return;}
  const current=rows(),next=selectedAnnotation?current.map(s=>s.id===selectedAnnotation?row:s):[...current,row];setRows(next);resetEditor();renderRows();status('Annotation enregistrée.');
 },opts);
 document.addEventListener('click',async e=>{
  const tab=e.target.closest('[data-c2-lab]');if(tab){document.querySelector('#c2-audio')?.pause();document.querySelector('[data-pangloss-audio]')?.pause();activeLab=tab.dataset.c2Lab;document.querySelector('#c2-lab').innerHTML=labMarkup();selectedWords=[];await initAudio();bindPanglossReader(signal);document.querySelector(`[data-c2-lab="${activeLab}"]`)?.focus({preventScroll:true});centerLabTab();return;}
  const slide=e.target.closest('[data-c2-slide]');if(slide){location.hash='/projection-chapitre-2/'+slide.dataset.c2Slide;return;}
  const word=e.target.closest('[data-c2-token]');if(word){if(selectedWords.length===2)selectedWords=[];selectedWords.push(Number(word.dataset.c2Token));updateSelection();return;}
  const removeText=e.target.closest('[data-c2-delete-text]');if(removeText){textAnnotations.splice(Number(removeText.dataset.c2DeleteText),1);document.querySelector('#c2-text-list').innerHTML=textList();return;}
  const edit=e.target.closest('[data-c2-edit]');if(edit){const row=rows().find(s=>s.id===edit.dataset.c2Edit);if(!row)return;selectedAnnotation=row.id;for(const [id,key] of [['c2-start','start'],['c2-end','end'],['c2-tier','tier'],['c2-annotation-text','text'],['c2-author','author']])document.getElementById(id).value=row[key];document.querySelector('#c2-save-segment').textContent='Enregistrer la modification';status('Modification de l’annotation sélectionnée.');drawWave();document.querySelector('#c2-annotation-text').focus();return;}
  const remove=e.target.closest('[data-c2-delete]');if(remove){setRows(rows().filter(s=>s.id!==remove.dataset.c2Delete));if(selectedAnnotation===remove.dataset.c2Delete)resetEditor();renderRows();status('Annotation supprimée.');return;}
  const action=e.target.closest('[data-c2-action]')?.dataset.c2Action;if(!action)return;
  if(action==='mark-start'||action==='mark-end'){const time=document.querySelector('#c2-audio').currentTime;document.querySelector(action==='mark-start'?'#c2-start':'#c2-end').value=time.toFixed(3);drawWave();}
  if(action==='new-segment')resetEditor();
  if(action==='play-selection'){const audio=document.querySelector('#c2-audio'),data=mediaData[scope()==='workshop'?'atelier':'demo'];if(!data)return;const segment=formSegment();const error=validateSegment({...segment,text:'Écoute'},data.duration);if(error){status(error);return;}audio.currentTime=segment.start;stopAt=segment.end;try{await audio.play();status('Écoute de l’intervalle sélectionné.');}catch{status('Lecture indisponible. Utilisez le lecteur audio ou téléchargez le média.');}}
  if(action==='export-csv'||action==='export-eaf'){if(!rows().length){status('Créez au moins une annotation avant de l’exporter.');return;}const name=scope()==='workshop'?'atelier':'demo';action==='export-csv'?download('annotations-'+name+'-chapitre2.csv',segmentsCsv(rows()),'text/csv;charset=utf-8'):download('annotations-'+name+'-chapitre2.eaf',segmentsEaf(rows(),name==='atelier'?'144254_HULUP_44k.mp3':'demo-voix.wav'),'application/xml;charset=utf-8');notify('Annotations exportées.');}
  if(action==='export-lexicon')download('lexique-demonstration.csv',toCsv(['Identifiant','Forme','Glose','Catégorie','Occurrences'],[['LEX-01','poisson',lexicalGloss,'nom','poisson ; poissons']]),'text/csv;charset=utf-8');
  if(action==='add-text-annotation'){if(selectedWords.length!==2){notify('Sélectionnez le premier et le dernier mot du passage.');return;}const lo=Math.min(...selectedWords),hi=Math.max(...selectedWords);textAnnotations.push({start:tokens[lo].start,end:tokens[hi].end,category:document.querySelector('#c2-category').value,author:document.querySelector('#c2-annotator').value,rationale:document.querySelector('#c2-rationale').value});document.querySelector('#c2-text-list').innerHTML=textList();selectedWords=[];updateSelection();}
  if(action==='export-text'){download('lectures-demonstration.json',JSON.stringify({source:writtenDemo,offsetUnit:'UTF-16, début inclus et fin exclue',annotations:textAnnotations},null,2),'application/json');notify('Lectures exportées.');}
  if(action==='export-evidence'){download('dossier-demonstration.md','# Dossier de démonstration — exemples fictifs\n\n## Mes liens entre formes et concepts pour P1\n\n'+conceptWords.map((word,i)=>word+' → '+conceptLinks[i]).join('\n')+'\n\n'+evidence.filter(x=>evidenceIds.has(x.id)).map(x=>`## ${x.id} — ${x.type}\n\n${x.text}\n`).join('\n')+'\n## Mon hypothèse, ses appuis et ses limites\n\n'+(hypothesis||'(Non renseigné)'),'text/markdown;charset=utf-8');notify('Dossier exporté.');}
  if(action==='export-workbook'){const notes=workbookFields.map(([id,label])=>`## ${label}\n\n${workbook.notes[id]||'(Non renseigné)'}\n`).join('\n');const annotated=workbook.segments.map(s=>`- ${s.start.toFixed(3)}–${s.end.toFixed(3)} s · ${s.tier} · ${s.author||'Auteur non renseigné'} : ${s.text}`).join('\n');download('carnet-chapitre2.md','# Carnet de numérisation de la parole — Chapitre 2\n\nSource : L’origine du kong Hulup, Pangloss / COCOON. Audio : https://doi.org/10.24397/pangloss-0000283 ; annotations : https://doi.org/10.24397/pangloss-0000282. Taï Waheo ; Françoise Ozanne-Rivierre ; Wadawa Hnyigootr. Son CC BY-NC-ND 2.5 ; annotations CC BY-NC-SA 2.5.\n\n'+notes+'\n## Mes annotations du récit en iaai\n\n'+(annotated||'(Aucune annotation temporelle)'),'text/markdown;charset=utf-8');notify('Carnet exporté.');}
  if(action==='save-workbook'){download('sauvegarde-chapitre2.json',JSON.stringify(workbook,null,2),'application/json');notify('Sauvegarde du chapitre 2 exportée.');}
 },opts);
 document.addEventListener('keydown',e=>{if(!location.hash.startsWith('#/projection-chapitre-2/'))return;if(e.target.closest('input,textarea,select,[contenteditable],audio'))return;const i=Number(location.hash.split('/')[2])||0;if(e.key==='ArrowRight'&&i<slides2.length-1){e.preventDefault();location.hash='/projection-chapitre-2/'+(i+1);}if(e.key==='ArrowLeft'&&i>0){e.preventDefault();location.hash='/projection-chapitre-2/'+(i-1);}if(e.key==='Escape'&&!document.fullscreenElement)location.hash='/chapitre/2';},opts);
 initAudio();bindPanglossReader(signal);centerLabTab();
}
